export const products: Product[] = Array.isArray(nexoCatalog) ? nexoCatalog as Product[] : fallbackProducts;

export const formatMoney = (n: number) =>
  new Intl.NumberFormat('es-CL', {
    style: 'currency',
    currency: 'CLP',
    maximumFractionDigits: 0,
  }).format(n);
